// @ts-nocheck
const IP_REGEX=/^((25[0-5]|2[0-4]\d|[01]?\d\d?)\.){3}(25[0-5]|2[0-4]\d|[01]?\d\d?)$/,PORT_MIN=1,PORT_MAX=65535,HEX_REGEX=/^[0-9A-Fa-f]+$/,PASSPORT_REGEX=/^(?=.*[0-9])(?=.*[a-z])(?=.*[A-Z]).{6,16}$/;export const getDefaultRules=(e,r=!1)=>{const t=[];switch(r&&t.push({required:!0,message:"此项为必填项"}),e){case"ip":t.push({pattern:IP_REGEX,message:"请输入正确的 IP 地址格式，如：192.168.1.1"});break;case"port":t.push({validator:(e,r)=>{if(null==r||""===r)return Promise.resolve();const t=Number(r);return isNaN(t)||t<1||t>65535?Promise.reject(new Error("端口号范围：1-65535")):Promise.resolve()}});break;case"hex":t.push({pattern:HEX_REGEX,message:"请输入正确的十六进制格式，如：1A2B3C"});break;case"passport":t.push({pattern:PASSPORT_REGEX,message:"密码长度6-16位，必须包含数字、大写字母和小写字母"})}return t};export const mergeRules=(e,r)=>r?(Array.isArray(r)||(r=[r]),[...e,...r]):e;export const getPlaceholder=(e,r)=>`${{input:"请输入",select:"请选择",ip:"请输入",port:"请输入",hex:"请输入",passport:"请输入",number:"请输入",number_range:"请输入",textarea:"请输入",radio:"请选择",radio_group:"请选择",checkbox:"请选择",checkbox_group:"请选择",date:"请选择",date_range:"请选择",cascader:"请选择",color:"请选择"}[e]||"请输入"}${r||""}`;export const normalizeItems=e=>Array.isArray(e)?e:e&&"object"==typeof e?Object.keys(e).map(r=>({field_name:r,...e[r]})):[];export const getOptionKeys=(e={})=>({valueKey:e.value||"key",labelKey:e.label||"value"});export const normalizeOptions=(e=[],r={})=>{const{valueKey:t,labelKey:a}=getOptionKeys(r);return e.map(e=>"string"==typeof e||"number"==typeof e?{value:e,label:String(e)}:{...e,value:e[t],label:e[a]})};